from load import *
import numpy as np, json, itertools
from collections import defaultdict
W={'arc_lite':0.04,'gsm_plus':0.02,'code_ms':0.025}
def own_range(rid):
    s=plan[rid]['suite']; lb=suites[s]['random_guess'] if suites[s]['scoring']=='raw' else 0.0
    c=cat(rid)
    if rid in ev: return (ev[rid],ev[rid])
    if rid in shard: return (shard[rid],shard[rid])
    if 'below_retention_floor' in c: return (lb, round(floor_at(ret[rid]['dropped_at'])-0.0001,4))
    if 'shard_file_lost' in c: return (floor_at(rt[rid]), 1.0)
    return (lb,1.0)
def rtype(rid):
    c=cat(rid); lo,hi=own_range(rid)
    if lo==hi: return 'known'
    if 'shard_file_lost' in c: return 'value'
    if 'below_retention_floor' in c: return 'range'
    return 'none'
byday=defaultdict(list)
for rid in launched: byday[rt[rid][:10]].append(rid)
def runs_of(cfg):
