def coefs(fr,to):
    Rf=runs_of(fr); Rt=runs_of(to); c={}
    for r in Rt: c[r]=c.get(r,0)+1/len(Rt)
    for r in Rf: c[r]=c.get(r,0)-1/len(Rf)
    return c
def day_width(day,c,boxes):
    """boxes: dict rid->(lo,hi) override (arrays allowed, broadcast). returns (maxv,minv) arrays or scalars; NaN where infeasible"""
    runs=byday[day]; T=digest[day][1]
    base=0.0; s=T; capP=0.0; capZ=0.0; capN=0.0
    cp=None; cn=None
    for r in runs:
        lo,hi=boxes.get(r,own_range(r))
        ci=c.get(r,0.0)
        base=base+ci*lo; s=s-lo
        if ci>1e-12: capP=capP+(hi-lo); cp=ci
        elif ci<-1e-12: capN=capN+(hi-lo); cn=ci
        else: capZ=capZ+(hi-lo)
    cp=cp or 0.0; cn=cn or 0.0
    s=np.asarray(s,dtype=float); capP=np.asarray(capP,float); capZ=np.asarray(capZ,float); capN=np.asarray(capN,float)
    feas=(s>=-1e-9)&(s<=capP+capZ+capN+1e-9)
    mx=base+cp*np.minimum(s,capP)+cn*np.maximum(0,s-capP-capZ)
    mn=base+cn*np.minimum(s,capN)+cp*np.maximum(0,s-capN-capZ)
    mx=np.where(feas,mx,np.nan); mn=np.where(feas,mn,np.nan)
    return mx,mn
def interval(c):
