        else: g=grid(lo,hi-w)
        axes.append((r,g))
    shp=[len(g) for _,g in axes]
    best=-1.0
    # build broadcast arrays
    arrs=[g.reshape([-1 if i==j else 1 for j in range(len(axes))]) for i,(_,g) in enumerate(axes)]
    for (name,g),arr in zip(axes,arrs):
        if name=='valsum':
            # replace vals boxes: first val run carries the whole sum as point; others as point at own lo... handled via base/s: set boxes so lo=hi=v_i.  Use: first run box=(arr - sum(other lo), same), others=(lo,lo)
            other=sum(own_range(r)[0] for r in vals[1:])
            boxes[vals[0]]=(arr-other,arr-other)
