        out['widths'][it['id']]=round(w,6); print(it['id'],it['recover'],[rtype(r) for r in it['recover']],w)
    for it in q['plans']:
        c=coefs(it['from'],it['to']); cands=it['candidates']
        # per-day precompute over subsets of candidates on that day
        days=defaultdict(list)
        for r in cands: days[rt[r][:10]].append(r)
        cache={}
        def gw(S):
