                key=(d,tuple(sorted(r for r in S if rt[r][:10]==d)))
                if key not in cache: cache[key]=day_guaranteed(d,c,list(key[1]))
                tot+=cache[key]
            return tot
        found=None
        for k in range(len(cands)+1):
            for S in itertools.combinations(cands,k):
                if gw(S)<=it['target']+1e-9: found=(k,list(S)); break
            if found: break
        out['plans'][it['id']]={'k':found[0],'runs':found[1]}; print(it['id'],found, gw(found[1]), 'target',it['target'], 'empty',gw([]))
    json.dump(out,open('/app/answers.json','w'),indent=1)
    print(json.dumps(out,indent=1))
